dtsPropsFor.BottomSheet:
/** Renders nothing when false. Portals into #sheet-root (provided by DsProvider). */
  open: boolean;
  onClose: () => void;
  title: React.ReactNode;
  children?: React.ReactNode;

dtsPropsFor.TopBar:
title: React.ReactNode;
  /** Shows a back chevron (navigate(-1)). Needs a router (DsProvider). */
  back?: boolean;
  /** Right-side slot (icon buttons...). */
  right?: React.ReactNode;

dtsPropsFor.EmptyState:
/** lucide icon component, rendered in a primary-50 circle. */
  icon?: React.ComponentType<{ size?: number; className?: string }>;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Call-to-action element (e.g. <button className="btn-primary">). */
  action?: React.ReactNode;

dtsPropsFor.StepProgress:
/** Current step, 1-based. */
  step: number;
  total: number;
  labels?: string[];
  /** With labels: renders clickable step chips instead of the "Etape n/total" line. */
  onStepClick?: (step: number) => void;
  /** Furthest step the user may jump to (defaults to step). */
  maxStepReached?: number;

dtsPropsFor.ContactFields:
/** Card title, e.g. "Expediteur" / "Destinataire". */
  title: React.ReactNode;
  data: { nom_prenom: string; telephone: string; adresse: string; ville: string; email?: string; societe?: string; code_postal?: string; etat?: string; quartier?: string };
  onChange: (data: ContactFieldsProps['data']) => void;
  /** Offer a commune <select> for ville. */
  communes?: { id: string | number; nom: string }[];
  /** Lock ville to this read-only value. */
  villeFixed?: string;

dtsPropsFor.DestinationCountrySheet:
open: boolean;
  onClose: () => void;
  /** Rows from GET pays-disponibles: ISO code + one boolean per expedition type. */
  destinations: { code_pays: string; nom?: string; ld?: boolean; groupage_afrique?: boolean; groupage_ca?: boolean; groupage_dhd_aerien?: boolean; groupage_dhd_maritime?: boolean }[];
  status: 'idle' | 'loading' | 'error';
  /** Filters to types usable with this mode. */
  mode?: 'livraison_domicile' | 'recuperation_agence';
  /** Code shown with a check mark. */
  currentCode?: string;
  onSelect: (code: string) => void;
  onRetry?: () => void;

dtsPropsFor.ProductSelectSheet:
open: boolean;
  onClose: () => void;
  products: { id: string | number; designation: string; reference: string; category?: { nom: string } }[];
  status: 'idle' | 'loading' | 'error';
  onSelect: (product: ProductSelectSheetProps['products'][number]) => void;

dtsPropsFor.SegmentedTabs:
tabs: { key: string; label: React.ReactNode; count?: number }[];
  /** Active tab key. */
  value: string;
  onChange: (key: string) => void;
  /** Unique id per tab group on a page (animated pill layoutId). Default "tabs". */
  id?: string;

dtsPropsFor.StatusBadge:
/** One of the exported dictionaries: COMMANDE_STATUTS, LIVRAISON_STATUTS, ANNONCE_STATUTS, ECHEANCE_STATUTS, PAIEMENT_ABONNEMENT_STATUTS. */
  map: Record<string, { label: string; short?: string; tone: 'neutral' | 'success' | 'warning' | 'info' | 'danger' }>;
  /** Key in map, e.g. "payee". Unknown values render as a neutral pill. */
  value: string;
  /** Use the entry's short label when it has one. */
  short?: boolean;
  className?: string;

dtsPropsFor.PersonRow:
label: React.ReactNode;
  /** Renders nothing when null. */
  person: { prenoms?: string; nom?: string } | null;

dtsPropsFor.PaymentInfoCard:
/** Renders nothing without payment_method_choisi. */
  commande: { payment_method_choisi?: 'mobile_money' | 'cash' | 'bank_transfer' | 'card' | 'other'; reference_paiement?: string; paiement_declare_le?: string; preuve_paiement_path?: string };
  title?: string;

dtsPropsFor.ImageGallery:
/** Empty array renders an ImageOff placeholder. */
  photos: { id?: string | number; url: string }[];
  /** Element layered over the main image (badges, favorite button). */
  overlay?: React.ReactNode;

dtsPropsFor.PhotoPicker:
/** Selected images; the first is the cover. */
  files: File[];
  onChange: (files: File[]) => void;
  /** Default 10. */
  max?: number;

dtsPropsFor.ProofPicker:
file: File | null;
  onChange: (file: File | null) => void;
  label?: string;

dtsPropsFor.AnimatedNumber:
/** Counts up from 0 to value. */
  value: number;
  /** e.g. (n) => n.toLocaleString('fr-FR') + ' FCFA'. */
  format?: (n: number) => React.ReactNode;
  className?: string;
